html='''<!doctype html><html><meta charset="utf-8"><style>body{background:#20252d;color:white;font:16px system-ui}canvas{background:#292b30}p{max-width:1000px}</style><p>ประกอบชิ้นส่วนท่ายืน · อยู่ระหว่างตรวจขนาดและรอยต่อ</p><canvas id="c" width="1024" height="512"></canvas><script>const D=__DATA__,c=document.getElementById('c'),x=c.getContext('2d'),cache=new Map(),parts=new Map();function load(path){return new Promise((ok,no)=>{let im=new Image();im.onload=()=>{cache.set(path,im);ok()};im.onerror=no;im.src=path})}Promise.all([...new Set([...D.parts.map(p=>p.image),'../ro-core-views-v52/neutral/W.png'])].map(load)).then(()=>{for(const p of D.parts){const a=document.createElement('canvas');a.width=a.height=512;let q=a.getContext('2d');q.drawImage(cache.get(p.image),...p.rect,...p.translation,p.rect[2]*p.scale,p.rect[3]*p.scale);parts.set(p.name,a)}for(const name of D.order)x.drawImage(parts.get(name),0,0);x.drawImage(cache.get('../ro-core-views-v52/neutral/W.png'),544,0);window.READY=true});window.study={data:D,part(n){return parts.get(n).toDataURL('image/png')},composite(){const a=document.createElement('canvas');a.width=a.height=512;const q=a.getContext('2d');for(const name of D.order)q.drawImage(parts.get(name),0,0);return a.toDataURL('image/png')}};</script></html>''';(P/'rest-review.html').write_text(html.replace('__DATA__',json.dumps(data,separators=(',',':'))))
